<section data-version="<%= @game.version %>" <%= "data-ended" if @game.ended? %>>
  <% if @game.lobby? %>
    <div class="lobby">
      <div>
        <h1 class="lobby__title"><%= @game.title %></h1>
        <p class="lobby__join">Join on your phone</p>
        <% join_url = play_url(@game.code) %>
        <p class="lobby__url"><%= join_url %></p>
        <p class="counter-pill" data-counter><%= @counter %></p>
        <% if @game.round_count.zero? %><p>No active questions</p><% end %>
      </div>
      <div class="qr" role="img" aria-label="QR code for the join link">
        <%= join_qr_svg(join_url) %>
      </div>
    </div>
  <% elsif @game.ended? %>
    <p class="stage-question__num"><%= @game.title %></p>
    <h1 class="lobby__title">The quiz is over</h1>
  <% else %>
    <p class="stage-question__num">Question <%= @game.round_number %> of <%= @game.round_count %></p>
    <h1 class="stage-question__body"><%= @round.prompt %></h1>
    <ol class="stage-options <%= 'stage-options--results' if @game.closed? %>">
      <% lettered_options(@round).each_with_index do |(option, letter), i| %>
        <% correct = @game.closed? && option["correct"] %>
        <li class="stage-option <%= 'is-correct' if correct %>">
          <span class="stage-option__letter" aria-hidden="true"><%= letter %></span>
          <span class="stage-option__title"><%= option["text"] %></span>
          <% if @game.closed? %>
            <% if correct %><span class="stage-option__mark">Correct</span><% end %>
            <strong class="stage-option__count"><%= @tallies.fetch(i, 0) %></strong>
          <% end %>
        </li>
      <% end %>
    </ol>
    <% if @game.open? %><p class="counter-pill" data-counter><%= @counter %></p><% end %>
  <% end %>
  <div class="screen-controls">
    <%= link_to "← Back to quiz", moderate_quiz_path(@game.quiz_id) %>
    <% unless @game.ended? %>
      <%= button_to stage_action(@game), advance_moderate_game_path(@game), params: { version: @game.version }, class: "btn btn--pink btn--lg" %>
    <% end %>
  </div>
</section>
